// Defends result sets that look like a code search rather than a match on
// "the" and "is": stopwords carry no weight, and an identifier matches the
// words it is made of.
func TestHashEmbedderDropsStopwordsAndSplitsIdentifiers(t *testing.T) {
	h := HashEmbedder{Dims: 256}
	if !reflect.DeepEqual(h.Vector("where is the retry logic"), h.Vector("retry logic")) {
		t.Error("stopwords changed the vector")
	}
	for _, ident := range []string{"retryLogic", "RetryLogic", "retry_logic"} {
		if !reflect.DeepEqual(h.Vector(ident), h.Vector("retry logic")) {
			t.Errorf("%s did not split into retry, logic", ident)
		}
	}
}

// encodeEmbeddingBinary converts a float32 slice to binary bytes (more efficient)
func encodeEmbeddingBinary(embedding []float32) []byte {
	size := len(embedding) * 4
	buf := GetEmbeddingBuffer(size)
	defer PutEmbeddingBuffer(buf)

	result := make([]byte, size)
	for i, v := range embedding {
		binary.LittleEndian.PutUint32(result[i*4:], math.Float32bits(v))
	}
	return result
}

// encodeEmbedding converts a float32 slice to binary for storage (~3x smaller than JSON)
func encodeEmbedding(embedding []float32) ([]byte, error) {
	buf := make([]byte, len(embedding)*4)
	for i, v := range embedding {
		bits := math.Float32bits(v)
		buf[i*4] = byte(bits)
		buf[i*4+1] = byte(bits >> 8)
		buf[i*4+2] = byte(bits >> 16)
		buf[i*4+3] = byte(bits >> 24)
	}
	return buf, nil
}

// CompactEmbedding reduces precision for storage (optional memory savings)
// Converts float32 embeddings to int8 quantized values (-127 to 127)
// This reduces memory by 75% but loses some precision
type CompactEmbedding struct {
	Data   []int8
	Scale  float32
	Offset float32
}

// decodeEmbedding converts bytes back to a float32 slice
func decodeEmbedding(data []byte) ([]float32, error) {
	if len(data)%4 != 0 {
		// Fallback: try JSON decode for legacy data
		slog.Debug("decodeEmbedding using JSON fallback for legacy data", "data_len", len(data))
		var embedding []float32
		if err := json.Unmarshal(data, &embedding); err != nil {
			return nil, fmt.Errorf("invalid embedding data")
		}
		return embedding, nil
	}
	embedding := make([]float32, len(data)/4)
	for i := range embedding {
		bits := uint32(data[i*4]) | uint32(data[i*4+1])<<8 | uint32(data[i*4+2])<<16 | uint32(data[i*4+3])<<24
		embedding[i] = math.Float32frombits(bits)
	}
	return embedding, nil
}

func BenchmarkJSONEncoding(b *testing.B) {
	embedding := make([]float32, 1024)
	for i := range embedding {
		embedding[i] = float32(i) / 1024.0
	}

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		data, _ := encodeEmbedding(embedding)
		_, _ = decodeEmbedding(data)
	}
}

// Quantize converts a float32 embedding to a quantized form
func Quantize(embedding []float32) *CompactEmbedding {
	if len(embedding) == 0 {
		return nil
	}

	// Find min and max
	minVal := embedding[0]
	maxVal := embedding[0]
	for _, v := range embedding[1:] {
		if v < minVal {
			minVal = v
		}
		if v > maxVal {
			maxVal = v
		}
	}

	// Calculate scale and offset for mapping to 0-254 range
	valueRange := maxVal - minVal
	var scale float32
	if valueRange == 0 {
		scale = 1.0
	} else {
		scale = valueRange / 254.0
	}
	offset := minVal

	// Quantize values to 0-254 range, stored as int8 (shifted by -127)
	data := make([]int8, len(embedding))
	for i, v := range embedding {
		// Map to 0-254 range
		normalized := (v - offset) / scale
		// Shift to -127 to 127 for int8 storage
		shifted := normalized - 127.0
		if shifted < -127 {
			shifted = -127
		}
		if shifted > 127 {
			shifted = 127
		}
		data[i] = int8(shifted)
	}

	return &CompactEmbedding{
		Data:   data,
		Scale:  scale,
		Offset: offset,
	}
}
